#pragma once
#include "gust_field.hpp"

// AI: below section was generated by an AI
// Eulerian incompressible flow: self-advection, viscosity, pressure projection
// and vorticity confinement. Vortices inject momentum, not leaf trajectories.
constexpr int FLOW_WIDTH = 16;
constexpr int FLOW_HEIGHT = 8;
constexpr int FLOW_CELLS = FLOW_WIDTH * FLOW_HEIGHT;
constexpr float FLOW_STEP_SECONDS = 1.0f / 30.0f;
// The grid's own pull toward the mean wind. About 0.5 s, so eddies and wakes
// persist and drift, independent of the per-particle gust response sliders.
constexpr float FLOW_RELAX_PER_SECOND = 2.0f;
// Extra swirl forcing while a gust passes. The slower grid needs a stronger
// kick to build eddies within a one-to-two second burst.
constexpr float FLOW_GUST_SWIRL_BOOST = 2.5f;
constexpr unsigned FLOW_SWIRLS = 3;
constexpr uint32_t FLOW_SWIRL_LIFE_MS = 8192;

struct SwirlSource {
  float x, y, radius, spin;
};

struct FlowField {
  float u[FLOW_CELLS], v[FLOW_CELLS];
  float workU[FLOW_CELLS], workV[FLOW_CELLS];
  float pressure[FLOW_CELLS], divergence[FLOW_CELLS];
  float accumulator;
};

inline int flowIndex(int x, int y) {
  x = (x + FLOW_WIDTH) % FLOW_WIDTH;
  y = max(0, min(FLOW_HEIGHT - 1, y));
  return y * FLOW_WIDTH + x;
}

inline float flowSample(const float *values, float x, float y) {
  x -= floorf(x / FLOW_WIDTH) * FLOW_WIDTH;
  y = flowClamp(y, 0, FLOW_HEIGHT - 1.0f);
  const int ix = int(x), iy = int(y);
  const float fx = x - ix, fy = y - iy;
  const float top = values[flowIndex(ix, iy)] * (1 - fx) + values[flowIndex(ix + 1, iy)] * fx;
  const float bottom = values[flowIndex(ix, iy + 1)] * (1 - fx) + values[flowIndex(ix + 1, iy + 1)] * fx;
  return top * (1 - fy) + bottom * fy;
}

// Periodic horizontal boundaries; depth edges prohibit normal flow.
inline void projectFlow(FlowField &field, float dx, float dy) {
  const float ax = 1 / (dx * dx), ay = 1 / (dy * dy);
  for (int y = 0; y < FLOW_HEIGHT; y++) for (int x = 0; x < FLOW_WIDTH; x++) {
    const int i = flowIndex(x, y);
    field.divergence[i] = (field.u[flowIndex(x + 1, y)] - field.u[flowIndex(x - 1, y)]) / (2 * dx)
      + (field.v[flowIndex(x, y + 1)] - field.v[flowIndex(x, y - 1)]) / (2 * dy);
    field.pressure[i] = 0;
  }
  for (unsigned iteration = 0; iteration < 18; iteration++) {
    for (int y = 0; y < FLOW_HEIGHT; y++) for (int x = 0; x < FLOW_WIDTH; x++) {
      const int i = flowIndex(x, y);
      field.pressure[i] = (ax * (field.pressure[flowIndex(x - 1, y)] + field.pressure[flowIndex(x + 1, y)])
        + ay * (field.pressure[flowIndex(x, y - 1)] + field.pressure[flowIndex(x, y + 1)])
        - field.divergence[i]) / (2 * (ax + ay));
    }
  }
  for (int y = 0; y < FLOW_HEIGHT; y++) for (int x = 0; x < FLOW_WIDTH; x++) {
    const int i = flowIndex(x, y);
    field.u[i] -= (field.pressure[flowIndex(x + 1, y)] - field.pressure[flowIndex(x - 1, y)]) / (2 * dx);
    field.v[i] -= (field.pressure[flowIndex(x, y + 1)] - field.pressure[flowIndex(x, y - 1)]) / (2 * dy);
    if (y == 0 || y == FLOW_HEIGHT - 1) field.v[i] = 0;
  }
}

// Calibration anchors in m/s. Friction and perspective apply afterward.
inline float groundFlowSpeed(float mps) {
  static const float winds[] = {0, 2, 3, 4, 5, 8, 10, 15, 20, 25.5f};
  static const float speeds[] = {0, 0.15f, 0.9f, 2.2f, 4, 10, 14, 23, 30, 34};
  mps = flowClamp(mps, 0, 25.5f);
  for (unsigned i = 1; i < 10; i++) {
    if (mps <= winds[i]) return speeds[i - 1] + (speeds[i] - speeds[i - 1])
      * (mps - winds[i - 1]) / (winds[i] - winds[i - 1]);
  }
  return speeds[9];
}

inline void stepGroundFlow(FlowField &field, float panelWidth, float meanMps, float gustMps,
                           uint8_t activity, bool blowLeft, float panelStart, uint32_t now,
                           float airHeight = 0, float airMean = 0, float turbulenceGain = 1,
                           const GustTuning &tuning = DEFAULT_GUST_TUNING) {
  const bool airborne = airHeight > 0;
  const float worldWidth = max(3.0f, panelWidth * (airborne ? 1 : 3));
  const float dx = worldWidth / FLOW_WIDTH, dy = (airborne ? airHeight : 24.0f) / FLOW_HEIGHT;
  const float dt = FLOW_STEP_SECONDS;
  const float direction = blowLeft ? -1.0f : 1.0f;
  const float mean = airborne ? airMean : groundFlowSpeed(meanMps);
  // The local gust stream is applied to particles after pressure projection.
  // Project only the baseline and evolving vortices, so incompressibility
  // does not smear a brief kick into a slow, scene-wide speed change.
  // Spatial sources disturb strong sustained wind; gusts feed them harder.
  // The solver carries and reshapes their wakes after the forcing subsides.
  const float domainHeight = airborne ? airHeight : 24.0f;
  SwirlSource swirls[FLOW_SWIRLS];
  for (unsigned source = 0; source < FLOW_SWIRLS; source++) {
    // Staggered lifetimes keep roughly two sources alive. Each appears at a
    // fresh hashed spot, drifts downwind with the mean flow and fades out.
    // The lifetime divides millis' range, so rollover stays continuous.
    const uint32_t swirlTime = now + source * (FLOW_SWIRL_LIFE_MS / FLOW_SWIRLS);
    const uint32_t hash = gustHash((swirlTime / FLOW_SWIRL_LIFE_MS) * 31U + source * 7919U + 13U);
    const float age = float(swirlTime % FLOW_SWIRL_LIFE_MS) / FLOW_SWIRL_LIFE_MS;
    float centerX = worldWidth * (hash & 1023U) / 1024.0f
      + direction * mean * age * FLOW_SWIRL_LIFE_MS / 1000.0f;
    centerX -= floorf(centerX / worldWidth) * worldWidth;
    swirls[source] = {
      centerX,
      domainHeight * (0.2f + ((hash >> 10) & 255U) / 425.0f),
      airborne ? max(2.0f, airHeight * 0.3f) : 5.0f + source,
      // sin(pi*age) averages 2/pi; 1.5 keeps the mean forcing near its old level.
      1.5f * sinf(3.1415927f * age) * ((hash >> 18) & 1U ? -1.0f : 1.0f),
    };
  }
  const float blend = min(1.0f, FLOW_RELAX_PER_SECOND * dt);
  for (int y = 0; y < FLOW_HEIGHT; y++) for (int x = 0; x < FLOW_WIDTH; x++) {
    const int i = flowIndex(x, y);
    const float depth = (y + 0.5f) / FLOW_HEIGHT;
    const float scale = airborne ? 1 : 1 / (3 - 2 * depth);
    const float worldX = (x + 0.5f) * dx - (airborne ? 0 : panelWidth);
    const float screenX = panelWidth * 0.5f + (worldX - panelWidth * 0.5f) * scale;
    const float pulse = gustFieldStrength(screenX + panelStart, now, blowLeft, activity, tuning);
    const float localMps = meanMps + (gustMps - meanMps) * pulse;
    const float target = direction * mean;
    // The grid relaxes at its own rate; the leaf response and settling
    // sliders act on particles only, so wakes outlive a sharp gust setting.
    field.u[i] += (target - field.u[i]) * blend;
    field.v[i] *= 1 - blend;
    float forceU = 0, forceV = 0;
    // Forcing scales with the relaxation rate, so swirl amplitude does not
    // depend on how quickly the grid returns to the mean.
    const float turbulence = max(0.0f, localMps - 2.0f) * (0.55f + pulse * FLOW_GUST_SWIRL_BOOST)
      * (1 + max(0.0f, localMps - 6.0f) * 0.12f) * turbulenceGain * FLOW_RELAX_PER_SECOND * 0.5f;
    for (const SwirlSource &swirl : swirls) {
      float rx = (x + 0.5f) * dx - swirl.x;
      rx -= floorf(rx / worldWidth + 0.5f) * worldWidth;
      const float ry = (y + 0.5f) * dy - swirl.y;
      const float weight = max(0.0f, 1 - (rx * rx + ry * ry) / (swirl.radius * swirl.radius));
      const float spin = swirl.spin * direction * turbulence * weight;
      forceU -= ry * spin;
      forceV += rx * spin;
    }
    field.u[i] += forceU * dt;
    field.v[i] += forceV * dt;
  }
  // Curl uses the divergence scratch array until confinement ends.
  for (int y = 0; y < FLOW_HEIGHT; y++) for (int x = 0; x < FLOW_WIDTH; x++) {
    field.divergence[flowIndex(x, y)] =
      (field.v[flowIndex(x + 1, y)] - field.v[flowIndex(x - 1, y)]) / (2 * dx)
      - (field.u[flowIndex(x, y + 1)] - field.u[flowIndex(x, y - 1)]) / (2 * dy);
  }
  for (int y = 1; y < FLOW_HEIGHT - 1; y++) for (int x = 0; x < FLOW_WIDTH; x++) {
    const int i = flowIndex(x, y);
    const float nx = (fabsf(field.divergence[flowIndex(x + 1, y)]) - fabsf(field.divergence[flowIndex(x - 1, y)])) / (2 * dx);
    const float ny = (fabsf(field.divergence[flowIndex(x, y + 1)]) - fabsf(field.divergence[flowIndex(x, y - 1)])) / (2 * dy);
    const float length = sqrtf(nx * nx + ny * ny) + 0.001f;
    field.u[i] += dt * 0.6f * ny / length * field.divergence[i];
    field.v[i] -= dt * 0.6f * nx / length * field.divergence[i];
  }
  projectFlow(field, dx, dy);
  for (int y = 0; y < FLOW_HEIGHT; y++) for (int x = 0; x < FLOW_WIDTH; x++) {
    const int i = flowIndex(x, y);
    const float sx = x - dt * field.u[i] / dx, sy = y - dt * field.v[i] / dy;
    field.workU[i] = flowSample(field.u, sx, sy);
    field.workV[i] = flowSample(field.v, sx, sy);
    const float lapU = field.u[flowIndex(x - 1, y)] + field.u[flowIndex(x + 1, y)]
      + field.u[flowIndex(x, y - 1)] + field.u[flowIndex(x, y + 1)] - 4 * field.u[i];
    const float lapV = field.v[flowIndex(x - 1, y)] + field.v[flowIndex(x + 1, y)]
      + field.v[flowIndex(x, y - 1)] + field.v[flowIndex(x, y + 1)] - 4 * field.v[i];
    field.workU[i] = flowClamp(field.workU[i] + 0.006f * lapU, -75, 75);
    field.workV[i] = flowClamp(field.workV[i] + 0.006f * lapV, -25, 25);
  }
  memcpy(field.u, field.workU, sizeof(field.u));
  memcpy(field.v, field.workV, sizeof(field.v));
  projectFlow(field, dx, dy);
}
// AI: end
